const html = $('Loop Over Items1').first().json.data || '';

// Limpieza del texto visible
const clean = html
  .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, '')
  .replace(/<\/?[^>]+(>|$)/g, '') // eliminar etiquetas HTML
  .slice(0, 3000); // limitar longitud

// Extracción de colores
const colorRegex = /(#(?:[0-9a-f]{3}){1,2}|rgb\([^)]+\)|rgba\([^)]+\))/gi;
const colores = html.match(colorRegex) || [];

return [{
  json: {
    cleanText: clean,
    colores: colores
  }
}];

try {
  // Obtener la URL desde $input.first().json.Web
  let url = $input.first().json.Web;

  // Verificar que la URL existe
  if (!url || typeof url !== 'string') {
    throw new Error('URL no válida o inexistente en el campo Web');
  }

  // Limpiar espacios en blanco
  url = url.trim();

  // Asegurar que tiene protocolo (agregar http:// si no tiene ninguno)
  if (!url.match(/^https?:\/\//)) {
    url = 'http://' + url;
  }

  // Cambiar http:// a https://
  url = url.replace(/^http:\/\//, 'https://');

  // Eliminar www. si existe
  url = url.replace(/^https:\/\/www\./, 'https://');

  // Asegurar que termine con /
  if (!url.endsWith('/')) {
    url += '/';
  }

  // Retornar solo la URL limpia
  return url;

} catch (error) {
  // En caso de error, retornar mensaje de error
  return `Error: ${error.message}`;
}

